<?php namespace App\Http\Controllers\Api;use App\Http\Controllers\Controller;use Illuminate\Http\Request;use Illuminate\Support\Facades\Hash;class AuthController extends Controller{public function login(Request $r){$data=$r->validate(['email'=>'required|email','password'=>'required']);$user=\App\Models\User::where('email',$data['email'])->first();if(!$user||!Hash::check($data['password'],$user->password))return response()->json(['message'=>'E-mail ou senha inválidos.'],422);$user->tokens()->delete();return ['token'=>$user->createToken('rbek-web')->plainTextToken,'user'=>$user];}public function me(Request $r){return $r->user();}public function logout(Request $r){$r->user()->currentAccessToken()?->delete();return response()->noContent();}}
